local r=fu:GetResolve();local pm=r:GetProjectManager();local p=pm:GetCurrentProject();assert(not p:IsRenderingInProgress(),'Current project render in progress');assert(pm:SaveProject());print('PRESERVED',p:GetName());if p:GetName()~='Motilli Podcast DVHp v5 20260909' then p=pm:LoadProject('Motilli Podcast DVHp v5 20260909') end;assert(p and p:GetName()=='Motilli Podcast DVHp v5 20260909');local old=nil;for i=1,p:GetTimelineCount() do local t=p:GetTimelineByIndex(i);if t:GetName()=='Motilli Podcast v5 Final 04' then old=t end;assert(t:GetName()~='Motilli Podcast v6 Visual Revision','v6 already exists') end;assert(old);local t=old:DuplicateTimeline('Motilli Podcast v6 Visual Revision');assert(t);assert(p:SetCurrentTimeline(t));assert(pm:SaveProject());print('READY',t:GetName(),t:GetEndFrame())
